#!/usr/bin/env python3
# Powermove: derives src/libfx_core_runtime.zig from upstream's
# src/napi_core_main.zig (patch P-CAPI). The N-API entry's runtime, queues,
# attachment table, fetch bridge and runtime slots have no Node-API in them;
# they are copied verbatim, by declaration name, so a re-pin re-extracts them
# instead of hand-merging. Only the Node-API surface (and the output queue,
# which the C entry replaces with a typed frame sink) is left behind.
#
# usage: extract-core-runtime.py <upstream napi_core_main.zig> <out.zig>
import re
import sys

KEEP = [
    # name, kind ("const" = `const X = ...;` block, "fn" = function)
    ("max_drain_bytes", "const"),
    ("max_input_bytes", "const"),
    ("max_fetch_request_bytes", "const"),
    ("max_bridge_request_body_bytes", "const"),
    ("bridgeBound", "fn"),
    ("configuredBridgeBundle", "fn"),
    ("max_fetch_response_bytes", "const"),
    ("max_attachment_bytes", "const"),
    ("max_inbound_attachments", "const"),
    ("max_inbound_attachment_bytes", "const"),
    ("max_outbound_attachments", "const"),
    ("max_outbound_attachment_bytes", "const"),
    ("max_api_key_bytes", "const"),
    ("max_model_bytes", "const"),
    ("max_effort_bytes", "const"),
    ("max_path_bytes", "const"),
    ("max_url_bytes", "const"),
    ("max_active_runtimes", "const"),
    ("ReadyNotifier", "const"),
    ("InputQueue", "const"),
    ("AttachmentTable", "const"),
    ("next_idle_wait", "const"),
    ("FetchBridge", "const"),
    ("FetchOperationResult", "const"),
    ("threaded_io", "var"),
    ("threaded_io_state", "var"),
    ("active_runtime_count", "var"),
    ("claimRuntimeSlot", "fn"),
    ("releaseRuntimeSlot", "fn"),
    ("ensureThreadedIo", "fn"),
]

# Upstream imports the runtime pieces use; node_api and the entry-only ones
# are dropped.
IMPORTS = [
    "std", "acp_server", "jsonrpc", "gateway_provider", "provider_set", "stream_provider",
    "agent_steps", "context_contract", "host", "host_attachments", "agent_checkpoint", "io_mod",
    "fetch_state", "http_config", "host_stream_provider", "host_openai_codex", "openai_codex",
    "host_xai_grok", "host_chat_completions", "configured_provider", "provider_catalog",
    "model_provider", "oauth_transport", "builtin_gateway", "builtin_modes",
]


def decl_span(lines, name, kind):
    """Line range [start, end) of a top-level declaration, with its doc comments."""
    if kind == "fn":
        pat = re.compile(r"^(pub )?fn " + re.escape(name) + r"\(")
    else:
        pat = re.compile(r"^(pub )?(const|var) " + re.escape(name) + r"\b")
    for i, line in enumerate(lines):
        if pat.match(line):
            start = i
            while start > 0 and lines[start - 1].startswith("//"):
                start -= 1
            # Top-level declarations end at the first later line that is
            # back at column 0 with a closing brace, or on their own line.
            if lines[i].rstrip().endswith(";"):
                return start, i + 1
            end = i + 1
            while not (lines[end].startswith("}")):
                end += 1
            return start, end + 1
    raise SystemExit(f"declaration not found upstream: {name}")


def main():
    src, out = sys.argv[1], sys.argv[2]
    lines = open(src, encoding="utf-8").read().split("\n")
    header = [
        "// Powermove notice: generated by tools/extract-core-runtime.py from",
        "// upstream src/napi_core_main.zig (patch P-CAPI). The declarations below",
        "// are upstream's, verbatim; do not edit them here, change the extractor",
        "// or the C entry instead. Only `pub` was added so src/capi_core_main.zig",
        "// can use them.",
    ]
    body = []
    for line in lines:
        m = re.match(r"^const (\w+) = @import\(", line)
        if m and m.group(1) in IMPORTS:
            body.append("pub " + line)
    body.append("")
    body.append("pub const Allocator = std.mem.Allocator;")
    for name, kind in KEEP:
        start, end = decl_span(lines, name, kind)
        chunk = lines[start:end]
        first = next(i for i, l in enumerate(chunk) if not l.startswith("//"))
        if not chunk[first].startswith("pub "):
            chunk[first] = "pub " + chunk[first]
        body.append("")
        body.extend(chunk)
    # The C entry needs the FetchBridge methods and fields it drives directly.
    text = "\n".join(header + [""] + body) + "\n"
    for method in ("open", "statusFn", "retryAfterFn", "next", "close", "markConsumed",
                   "disposition", "startResponse", "pushResponse", "finishResponse",
                   "failResponse", "is_active", "abort", "shutdown", "deinit", "init",
                   "notify", "read", "write", "store", "takeOutbound", "discardInbound",
                   "clearPendingRequest"):
        text = re.sub(r"^(    )fn " + method + r"\(", r"\1pub fn " + method + "(", text, flags=re.M)
    open(out, "w", encoding="utf-8").write(text)


main()
